"""Write the chapter JSON files of the brief Shaddad user manual (build/build_manual.js reads them)."""
import json
import os

D = os.path.dirname(os.path.abspath(__file__))
PRJ = r"C:\Users\aomar\Desktop\Robot project\Shaddad_UGV.prj"

chapters = []

chapters.append({"id": "um01_start", "title": "Before You Start", "blocks": [
    {"type": "p", "text": "This manual explains how to run the Shaddad UGV digital twin, the MATLAB/Simulink/Simscape model of NASL's tracked agricultural platform, in **Phase 1**: driving the robot by remote control, either with a scripted plan or live with a PS5 controller or an RC transmitter, with a 3-D view of the robot. The run includes the full chain from the transmitter through the STM32 firmware, the motor controllers and motors to the tracks, powered by the 48 V battery and BMS."},
    {"type": "h2", "text": "Quick start"},
    {"type": "p", "text": "Six commands cover the normal workflow:"},
    {"type": "code", "text": "openProject('" + PRJ + "');   % load data, print the startup report\n"
                             "res = phase1_test_drive();      % scripted RC drive: summary, figure, replay (about 5 min)\n"
                             "res = phase1_live_drive();      % drive live with a PS5 controller or RC transmitter, 3-D view\n"
                             "plot_run(res);                  % plot every signal of the run (six pages)\n"
                             "r1  = run_scenario('S1');       % RC acceptance scenario, 120 s simulated (about 5-6 min)\n"
                             "rt  = run_regression('Fast');   % fast regression checks (about 1-3 min)"},
    {"type": "h2", "text": "What you need"},
    {"type": "table", "id": "tab_req", "caption": "Requirements", "header": ["Item", "Requirement"], "widths": [26, 74], "rows": [
        ["MATLAB", "R2026b with Simulink"],
        ["Required products", "Simscape, Simscape Electrical, Simscape Battery, Motor Control Blockset, Communications Toolbox, DSP System Toolbox (with Signal Processing Toolbox), Aerospace Blockset, Robotics System Toolbox, Navigation Toolbox, Sensor Fusion and Tracking Toolbox, Control System Toolbox, Model Predictive Control Toolbox, Embedded Coder, STM32 Microcontroller Blockset, ROS Toolbox"],
        ["Live drive", "Simulink 3D Animation (Simulation 3D Joystick block); a PS5 controller (USB or Bluetooth) or an RC transmitter with a USB joystick mode"],
        ["Optional", "Simulink Coder (code generation for the STM32), STM32CubeMX/CubeCLT and GNU Arm (board builds), MinGW-w64 compiler (Accelerator mode)"],
        ["PC", "Windows 11, 16 GB RAM minimum"],
    ]},
    {"type": "note", "kind": "warning", "text": "MATLAB memory grows by about 0.5-1 GB with every full-system compile. Check it with `m = memory; m.MemUsedMATLAB/1e9` and restart MATLAB before it reaches about 9 GB, otherwise the simulation slows down 4-5 times."},
]})

chapters.append({"id": "um02_open", "title": "Open the Project", "blocks": [
    {"type": "code", "text": "openProject('" + PRJ + "');"},
    {"type": "p", "text": "Opening the project puts all folders on the path and runs `scripts/shaddad_startup.m`, which:"},
    {"type": "bullets", "items": [
        "creates the parameters `P`, the sample times `Ts`, the variant controls `VC_*` and the 88 `Bus_*` objects in the base workspace;",
        "creates the configuration sets `cs_*` (fixed-step, 1 ms);",
        "prints a product report that shows what is installed ({fig:F16_matlab_desktop_crop.png}). `MISSING` next to Simulink Coder only means code generation is not available; simulation works.",
    ]},
    {"type": "figure", "file": "F16_matlab_desktop_crop.png", "caption": "MATLAB desktop with the Shaddad_UGV project open and the startup report in the Command Window."},
    {"type": "p", "text": "To look at the models in Simulink:"},
    {"type": "code", "text": "open_system('Shaddad_System');        % top model\n"
                             "open_system('Shaddad_MCU');           % STM32 firmware model\n"
                             "close_system('Shaddad_System', 0);    % close without saving"},
    {"type": "note", "kind": "info", "text": "Never edit and save the `.slx` files by hand. Every model is generated by a script in `scripts/build/` (see {sec:um07_params})."},
    {"type": "table", "id": "tab_folders", "caption": "Folders you will use", "header": ["Folder", "Contents"], "widths": [22, 78], "rows": [
        ["`scripts/`", "`phase1_test_drive.m`, `run_scenario.m`; `scenarios/` holds the scenario definitions; `build/` the model generators"],
        ["`params/`", "Parameter files `param_<domain>.m` and `shaddad_params.m`"],
        ["`models/`", "Top-level models: `Shaddad_System`, `Shaddad_Plant`, `Shaddad_MCU`, `Shaddad_BMS`"],
        ["`subsystems/`", "Component models per domain (structure, power, drive, electronics, rc, sensors)"],
        ["`tests/`", "Test classes and `run_regression.m`"],
        ["`work/`", "Generated: model cache, `results/` (run logs), `reports/` (test reports)"],
    ]},
]})

chapters.append({"id": "um03_drive", "title": "Drive the Robot with phase1_test_drive", "blocks": [
    {"type": "p", "text": "`phase1_test_drive` drives the robot with the simulated RC transmitter from a simple plan, then prints a summary, shows a results figure and plays a bird's-eye replay. It switches the transmitter on, arms the robot and puts it in MANUAL mode automatically."},
    {"type": "h2", "text": "The plan"},
    {"type": "p", "text": "A plan is an N x 3 matrix `[t v w]`: from time `t` [s], hold forward speed `v` [m/s] and yaw rate `w` [rad/s] until the next row. Positive `v` is forward, positive `w` is a **left** turn. Limits: |v| <= 2.0 m/s and |w| <= 1.0 rad/s (larger values are clipped)."},
    {"type": "table", "id": "tab_plan", "caption": "Default demo plan", "header": ["t [s]", "v [m/s]", "w [rad/s]", "Maneuver"], "widths": [14, 14, 16, 56], "rows": [
        ["0", "0", "0", "Power-up, arm at 2 s"], ["4", "0.8", "0", "Straight ahead"], ["14", "0.8", "0.3", "Left arc"],
        ["24", "1.2", "0", "Faster straight"], ["34", "0.5", "-0.4", "Right arc"], ["44", "0", "0.5", "Pivot turn in place"],
        ["50", "-0.4", "0", "Reverse"], ["56", "0", "0", "Stop (run ends at 64 s)"],
    ]},
    {"type": "h2", "text": "Examples"},
    {"type": "code", "text": "res = phase1_test_drive();                                  % default demo\n"
                             "plan = [0 0 0;  4 1.0 0;  15 1.0 0.4;  25 0 0];\n"
                             "res = phase1_test_drive('Plan', plan);                      % your own drive\n"
                             "res = phase1_test_drive('EStopAt', 20, 'ResetAt', 25);      % remote E-stop, then reset\n"
                             "res = phase1_test_drive('RCLoss', [20 23]);                 % radio link lost 20-23 s\n"
                             "res = phase1_test_drive('Implement', 1);                    % with the mower (2 tiller, 3 sprayer)\n"
                             "res = phase1_test_drive('Plan', plan, 'StopTime', 40, 'Replay', false);"},
    {"type": "p", "text": "For the E-stop and RC-loss options the script also performs the operator recovery: it centres the sticks, presses reset and cycles the arm switch, so the plan resumes afterwards."},
    {"type": "h2", "text": "Reading the output"},
    {"type": "p", "text": "The printed summary gives the MCU mode sequence (expected: BOOT -> SELFTEST -> STANDBY -> MANUAL at about 2 s), the distance and maximum speed, the battery use, the SBUS frame counts (rejected frames should be 0) and collisions. The figure ({fig:F23_d1_dashboard.png}) shows command vs actual speed and yaw rate, the path, the left/right track speeds, and the battery current with the MCU mode."},
    {"type": "figure", "file": "F23_d1_dashboard.png", "caption": "Results figure of the default demo: speed and yaw rate follow the RC commands within about 0.02 m/s and 0.01 rad/s; 34.8 m driven, 0 rejected SBUS frames."},
    {"type": "p", "text": "The run log is saved in `work/results/D1_<date>_<time>.mat` (path in `res.file`). The default 64 s drive takes about 4-6 min, because the simulation runs at about 0.3-0.5 times real time."},
]})

chapters.append({"id": "um04_scenarios", "title": "Run the Test Scenarios", "blocks": [
    {"type": "p", "text": "`run_scenario` runs a predefined test with pass/fail criteria and prints a criteria table (PASS, FAIL or BLOCKED)."},
    {"type": "code", "text": "r = run_scenario('S1');                    % RC drive, saved to work/results\n"
                             "r = run_scenario('S1', 'StopTime', 20);    % shorter run\n"
                             "r = run_scenario('S6c');                   % trailing letter = variant\n"
                             "r = run_scenario('S8', 'Variant', 'a', 'Viz', 1);   % live bird's-eye view\n"
                             "R = run_all_scenarios({'S0', 'S1', 'S6c'});         % several scenarios"},
    {"type": "table", "id": "tab_scn", "caption": "Phase 1 scenarios and latest results (2026-10-23, Normal mode)", "header": ["ID", "What it tests", "Result"], "widths": [9, 63, 28], "rows": [
        ["S0", "Power-up and safety re-arm timing", "PASS 11/11"],
        ["S1", "RC drive: speed step, steering, stop distance, reverse, RC latency", "PASS 12/13 (1 BLOCKED)"],
        ["S2", "20 deg ramp with a full sprayer: climb, hold, restart", "8/11"],
        ["S6a / S6b", "Radio link lost / silent SBUS line: controlled stop", "6/7 each"],
        ["S6c", "1 % corrupted SBUS bytes: frames rejected, keeps driving", "PASS 6/6"],
        ["S6d", "5 % corrupted bytes: link loss, controlled stop", "PASS 4/4"],
        ["S8a", "Front hardware E-stop, reset and restart", "PASS 6/6"],
        ["S8b", "Remote E-stop (CH12), latched", "5/6"],
    ]},
    {"type": "note", "kind": "info", "text": "BLOCKED means the criterion cannot be checked on this PC (S1 real-time-speed target needs Accelerator mode). The remaining failures are near-misses of stopping-deceleration limits (S6a/b, S8b) and the S2 tilt derating on the steep ramp."},
]})

chapters.append({"id": "um05_live", "title": "Drive Live with a PS5 Controller or RC Transmitter", "blocks": [
    {"type": "p", "text": "`phase1_live_drive` lets you drive the robot yourself and watch it in 3-D ({fig:F35_live3d_side.png}). Your controller feeds the simulated RC transmitter, so the commands pass the same SBUS frames, STM32 decoder, mode manager, safety logic, CAN, motor controllers, motors and tracks as in the tests. The controller is detected automatically: 6 axes and 13-18 buttons = PS5 layout, otherwise the RC transmitter layout."},
    {"type": "figure", "file": "F35_live3d_side.png", "caption": "Live 3-D view (side camera) with the mower: MCU mode, speed, belt speeds and SOC at the top, camera buttons and Stop at the right, the RC channels the MCU receives at the bottom right."},
    {"type": "h2", "text": "Start"},
    {"type": "code", "text": "phase1_joystick_check                          % first time: check sticks and buttons (close the window to end)\n"
                             "res = phase1_live_drive();                     % PS5 or RC transmitter (auto), 3-D view\n"
                             "res = phase1_live_drive('Implement', 1);       % with the mower (2 tiller, 3 sprayer)\n"
                             "res = phase1_live_drive('Camera', 2);          % 1 chase, 2 side, 3 top, 4 free (mouse)\n"
                             "res = phase1_live_drive('Source', 'demo');     % no controller: a scripted drive, same view\n"
                             "shaddad.Robot3DView.replay(res.file)           % replay any saved run in 3-D"},
    {"type": "note", "kind": "info", "text": "After `Controller found` MATLAB compiles the model for about 2-3 minutes (the first time) without further output; the 3-D window opens when the run starts. Wait for **STANDBY** in the HUD, keep the sticks centred, then arm."},
    {"type": "h2", "text": "PS5 controller"},
    {"type": "p", "text": "Connect it by USB cable or Bluetooth; no setup on the controller is needed. Its buttons spring back, so the model latches arm, E-stop, speed, HOLD, lights and implement."},
    {"type": "table", "id": "tab_ps5", "caption": "PS5 controls", "header": ["Control", "Action"], "widths": [32, 68], "rows": [
        ["Left stick up / down", "Throttle (forward / reverse)"],
        ["Right stick left / right", "Steering"],
        ["Cross", "Arm / disarm (sticks centred)"],
        ["Circle", "E-stop (latched, also disarms)"],
        ["Triangle (hold)", "Reset after an E-stop, then press Cross to arm again"],
        ["R1 / L1", "Speed scale up / down: 25 - 50 - 75 - 100 % (starts at 100 %)"],
        ["Options", "MANUAL / HOLD"],
        ["Square / Create", "Lights on / off; implement on / off"],
        ["L2 / R2 (held)", "Implement lift up / down"],
    ]},
    {"type": "h2", "text": "RC transmitter"},
    {"type": "p", "text": "Select **USB Joystick (HID)** on the radio (EdgeTX/OpenTX Classic mode: CH1-CH8 become axes 1-8, CH9 and up become buttons). If CH7 has no knob on your radio, set `scen.joy.ax(7) = 0` (full speed)."},
    {"type": "table", "id": "tab_rc", "caption": "RC transmitter controls", "header": ["Channel", "Action"], "widths": [32, 68], "rows": [
        ["CH2 / CH1", "Throttle / steering"],
        ["CH5 (3-pos)", "Low = MANUAL, middle = HOLD"],
        ["CH6", "Arm (switch on with the sticks centred)"],
        ["CH7", "Speed scale (knob)"],
        ["CH12", "Remote E-stop (latched); to continue: CH12 off, CH9 reset, cycle CH6"],
    ]},
    {"type": "p", "text": "Mappings are in `params/param_sim.m`: `scen.joy.pad` (PS5 axis and button numbers, dead zone) and `scen.joy.ax / inv / btn` (transmitter). Run `shaddad_params` after a change."},
    {"type": "h2", "text": "The 3-D view"},
    {"type": "figure", "file": "F37_live3d_sprayer.png", "caption": "Free camera with the sprayer: tank on the deck, boom with nozzles at the rear, tracks with moving tread bars, sprockets and road wheels."},
    {"type": "bullets", "items": [
        "Cameras: **Chase**, **Side**, **Top**, **Free** buttons or keys **1-4** (Free: rotate and zoom with the mouse).",
        "The tread bars move and the sprockets spin with the measured belt speeds; the trail shows the path.",
        "**Stop** button or **Esc** ends the run; the summary and the log file follow.",
        "Speed on the reference PC: about 0.85x real time with the view (1.07x without, about 0.6x with an implement). Simulation pacing caps the run at real time when the PC is fast enough.",
    ]},
    {"type": "note", "kind": "warning", "text": "The fast preset uses a kinematic chassis: no pitch or roll on slopes. Use `'Fidelity','full'` to see the body tilt (slower). The on-screen dashboard (`VC_OPSRC = 2`) does not work yet."},
]})

chapters.append({"id": "um06_results", "title": "Look at the Results", "blocks": [
    {"type": "p", "text": "`phase1_test_drive`, `phase1_live_drive` and `run_scenario` return a struct `res` and save the run in `work/results/<ID>_<date>_<time>.mat`. The most useful fields: `res.S` (all logged signals), `res.eval` (criteria), `res.ok`/`res.msg` (errors), `res.rtf` (speed) and `res.file` (saved log)."},
    {"type": "h2", "text": "Plot a run with plot_run"},
    {"type": "p", "text": "`plot_run` draws every logged signal of a run on six figure pages: **drive**, **tracks**, **battery**, **power**, **rc** and **nav**. It works for any saved run (live drive, test drive, scenarios); all six pages take about a minute."},
    {"type": "code", "text": "plot_run(res)                                 % the run just finished\n"
                             "plot_run('L1')                                % newest live drive (also 'D1', 'S1', ... or a log name)\n"
                             "plot_run(res, 'Pages', {'drive', 'battery'})  % some pages only\n"
                             "plot_run(res, 'TimeRange', [200 236])         % zoom; the time axes of a page move together\n"
                             "plot_run(res, 'Save', true)                   % PNGs in work/reports/plots_<log name>/"},
    {"type": "bullets", "items": [
        "Background bands on every time plot: **grey** = not armed (BOOT, SELFTEST, STANDBY), **yellow** = HOLD, **red** = ESTOP or FAULT.",
        "A tile whose signals the run did not log, or that stay at zero in the chosen model variant, shows a note instead of an empty line.",
        "Zoom and pan with the axes toolbar; all time plots of the page follow.",
    ]},
    {"type": "p", "text": "The figures below come from a 236 s live drive with the PS5 controller (log `L1_20261027_011510`): 141.7 m driven, top speed 2.0 m/s, no E-stop, no fault. The explanations say what each tile shows, what normal looks like and what this run shows."},
    {"type": "h3", "text": "Page 1 - drive: commands and response"},
    {"type": "figure", "file": "F38_plot_drive.png", "caption": "plot_run page drive: operator commands, speed and yaw-rate command vs response, path on the field and MCU mode."},
    {"type": "bullets", "items": [
        "**Operator commands:** throttle (CH2), steering (CH1) and the speed scale (CH7) as the MCU decoded them from the SBUS frames. Here the speed scale was 75 % from 20 s (L1) and 100 % from 212 s (R1).",
        "**Forward speed:** MCU target = stick x speed scale x 2.0 m/s; MCU reference = the target after the acceleration ramp; actual = true speed of the robot. The actual speed should follow the reference within a fraction of a second. A lasting gap means slip, a torque limit (page 2) or a battery limit (page 3).",
        "**Yaw rate:** the same for turning (+ = left), plus the gyro reading the MCU uses. In this run the gyro reading lags after hard turns and reads about -0.4 rad/s from 207 s while the robot drives straight; this is an open model issue (IMU model or gyro-bias correction) and goes with the IMU_FAULT warnings on page 5.",
        "**Path:** true path, coloured by speed; green dot = start, red square = end. The dashed green line is the edge of the field map (60 x 60 m in world 1); red points are outside the map, as in the last 17 s of this run.",
        "**MCU mode:** BOOT -> SELFTEST -> STANDBY within 1.1 s, MANUAL from arming (21.6 s) to the end. HOLD, ESTOP or FAULT would show here and as bands on all pages.",
    ]},
    {"type": "h3", "text": "Page 2 - tracks: tracks and motors"},
    {"type": "figure", "file": "F39_plot_tracks.png", "caption": "plot_run page tracks: track speeds, motor speeds, torques and limits, slip and motor power."},
    {"type": "bullets", "items": [
        "**Left / right track speed:** MCU reference (from the speed and yaw-rate references), measured (motor encoder), true belt speed and true ground speed. Belt faster than ground = slip. Negative values on one side are pivot turns.",
        "**Motor speed:** ESC setpoint (dashed) and actual motor speed in rpm; 2.0 m/s track speed is about 3,600 rpm.",
        "**Motor torque:** actual torque, MCU feed-forward torque (dotted) and the MCU motoring limit (dashed, 16 N m; lower when the MCU derates). Torque sitting on the limit means the robot cannot follow the reference.",
        "**Slip and traction control:** true slip = (belt - ground) / belt speed. Short spikes at low speed and in pivot turns are normal; long slip above about 0.2 while driving means poor traction. Traction factor 1 = no traction-control action.",
        "**Motor DC power and losses:** electrical input of each drive (negative = regenerative braking) and the losses in motor, ESC and gearbox (dotted).",
    ]},
    {"type": "h3", "text": "Page 3 - battery: battery and energy"},
    {"type": "figure", "file": "F40_plot_battery.png", "caption": "plot_run page battery: SOC, pack voltage, current and power, energy breakdown, cells, BMS limits and remaining energy."},
    {"type": "bullets", "items": [
        "**State of charge:** true SOC, BMS estimate, BMS coulomb count and the value the MCU receives over CAN. The BMS estimate should stay within a few tenths of a percent of the truth. Here: 95.0 % -> 94.7 %.",
        "**Pack voltage and current:** terminal voltage (truth and BMS) and pack current (+ = discharge). The voltage sags about 0.3 V at 45 A.",
        "**Power:** pack power = traction (both motors) + LV electronics (about 60 W) + losses.",
        "**Energy (cumulative):** energy out of the pack and where it went (traction, implement, LV electronics, losses). The title gives the total and the consumption per km: here 47.6 Wh, 336 Wh/km. Use it to compare drives, implements and soils.",
        "**Cell voltages:** the 16 cell groups (thin grey) and the BMS minimum and maximum. A spread below about 10 mV means a balanced pack.",
        "**Cell temperatures:** cells (thin), BMS maximum, pack air and ambient (45 degC in world 1).",
        "**BMS current limits:** discharge limit (DCL, 300 A) and charge limit (CCL, 100 A); the pack current must stay below them. The BMS lowers them with the cell temperature, near the cell voltage limits and (discharge) at low SOC.",
        "**Remaining energy and runtime:** BMS remaining energy (about 13 kWh) and the runtime at the present load (shown up to 24 h).",
    ]},
    {"type": "h3", "text": "Page 4 - power: power electronics, safety chain and temperatures"},
    {"type": "figure", "file": "F41_plot_power.png", "caption": "plot_run page power: low-voltage rails, HV bus, contactors and safety chain, conversion losses and temperatures."},
    {"type": "bullets", "items": [
        "**Low-voltage rails:** 24 V, 24 V implement, 12 V, 5 V and 3.3 V. A rail below its minimum sets the RAIL_UV bit (page 5).",
        "**HV bus and rail currents:** HV bus and pack voltage; 24 V and 12 V rail currents (about 1 A and 3.4 A here).",
        "**Contactors, safety chain and power flags:** one row per flag; a thick bar = true (green = normal, red = a problem flag, blue = information), a thin grey line = false. Normal driving: key on, K1 closed, BMS HV ready, MCU power ready, all rails OK, safety relay and both E-stop channels OK. The red mark at 0 s is the start-up.",
        "**Conversion losses:** DC/DC converter, power distribution unit (PDU) and the two drives.",
        "**Temperatures:** motor windings, housings and ESCs, enclosure (MCU) and ambient. Here the windings warmed from 45 degC to 53-56 degC in 4 minutes of driving.",
    ]},
    {"type": "h3", "text": "Page 5 - rc: RC link and MCU health"},
    {"type": "figure", "file": "F42_plot_rc.png", "caption": "plot_run page rc: all RC channels, radio link, SBUS counters, MCU fault and warning bits, command source and ESC states."},
    {"type": "bullets", "items": [
        "**RC channels:** all 14 channels after SBUS decoding (-1 to 1 around each line). Sticks move continuously; switches show as steps: here CH6 arm at 21.6 s, CH7 speed scale steps and CH11 lift pulses (L2 / R2, no effect without an implement).",
        "**Radio link quality and frame age:** link quality 0-1, lost single frames (red triangles; the simulated radio drops a few) and the age of the last good frame. Normal: below 30 ms. The MCU sets RC_LINK_LOST above 100 ms and stops the robot.",
        "**SBUS counters:** frames accepted (here 16,821 in 236 s, one frame every 14 ms); frames rejected, frames skipped and MCU task overruns should stay at 0.",
        "**MCU fault and warning bits:** only the bits that were set, by number and name (`docs/icd.md`). Orange = warning (condition present), red = fault (persisted or latched; stops or limits the robot). Here: start-up bits at 0 s (RC_LINK_LOST, RAIL_UV) and three short IMU_FAULT warnings at 214-225 s.",
        "**Command source and ESC states:** command source 1 = RC after arming; both ESCs go READY -> OPERATION when armed. FAULT or STO here explains a robot that stops.",
    ]},
    {"type": "h3", "text": "Page 6 - nav: navigation and vehicle dynamics"},
    {"type": "figure", "file": "F43_plot_nav.png", "caption": "plot_run page nav: navigation estimate vs truth, roll and pitch, accelerations, GNSS, navigation flags, slip and ground contact."},
    {"type": "bullets", "items": [
        "**Position estimate error and heading:** navigation estimate vs truth. In Phase 1 the navigation fusion does not run, so the position tile shows a note and only the true heading is drawn; Phase 2 runs show both.",
        "**Roll and pitch:** true attitude, the MCU estimate and the terrain grade. The fast preset has a kinematic chassis (true roll and pitch stay 0); the MCU estimate shows about +2 / -2 deg from the IMU. Tilt warnings start at 22 deg.",
        "**Body accelerations:** MCU acceleration reference, true forward and lateral acceleration, raw IMU x and y (they include a gravity part when the IMU is tilted).",
        "**GNSS:** fix type (4 = RTK fixed, reached after 4 s here), satellites (28) and the reported horizontal accuracy.",
        "**Navigation flags:** as on page 4. In Phase 1 only GNSS heading valid is true.",
        "**Track slip and ground contact:** true slip (plus the estimate in Phase 2) and the normal force on each track (constant 16.1 kN with the kinematic chassis; it changes on slopes with `'Fidelity','full'`).",
    ]},
    {"type": "h2", "text": "Raw signals"},
    {"type": "p", "text": "For your own plots: signals are grouped, for example `truth` (true vehicle motion), `telem` (MCU telemetry such as `mode`, `v_target`), `power_truth` (battery) and `drive_truth` (motors). Each signal has `.t` and `.v`."},
    {"type": "code", "text": "S = res.S;                      % or: r = load(res.file); S = r.S;\n"
                             "fieldnames(S.telem)             % list the signals of one group\n"
                             "figure; plot(S.truth.speed_fwd.t, S.truth.speed_fwd.v); grid on\n"
                             "xlabel('time [s]'); ylabel('forward speed [m/s]');\n"
                             "shaddad_replay_birdseye(res.file);   % replay the run from above"},
    {"type": "p", "text": "MCU mode numbers in `S.telem.mode`: 0 BOOT, 1 SELFTEST, 2 STANDBY, 3 MANUAL, 4 HOLD, 5 AUTO_START, 6 AUTO, 7 CTRL_STOP, 8 ESTOP, 9 FAULT."},
]})

chapters.append({"id": "um07_params", "title": "Change Parameters and Rebuild Models", "blocks": [
    {"type": "p", "text": "All numbers come from `params/param_<domain>.m` (structure, power, drive, electronics, rc, sensors, gnc, sim, world). Edit the file, then reload the parameters before the next run:"},
    {"type": "code", "text": "shaddad_params();                        % reload P after editing a param file\n"
                             "P.electronics.rcmap.deadband = 0.08;     % quick test: base workspace only, not saved"},
    {"type": "p", "text": "If you change model structure (blocks, wiring), change the build script and regenerate only the affected part:"},
    {"type": "code", "text": "build_drive({'esc'});          % regenerate one drive file\n"
                             "build_shaddad_mcu('model');    % regenerate the MCU model only"},
    {"type": "note", "kind": "warning", "text": "Do not run `build_shaddad_mcu()` or `build_shaddad_mcu('all')`: they overwrite the finished firmware units with stubs."},
]})

